ALTER TABLE public.mail ADD COLUMN poll_options text[] NOT NULL DEFAULT '{}', ADD COLUMN question_enabled boolean NOT NULL DEFAULT false, ADD COLUMN popup boolean NOT NULL DEFAULT false;
CREATE TABLE public.news_responses (mail_id uuid NOT NULL REFERENCES public.mail(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, choice integer, answer text NOT NULL DEFAULT '', reply text NOT NULL DEFAULT '', PRIMARY KEY(mail_id,user_id));
GRANT SELECT, INSERT, UPDATE ON public.news_responses TO authenticated; GRANT ALL ON public.news_responses TO service_role;
ALTER TABLE public.news_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY news_response_read ON public.news_responses FOR SELECT TO authenticated USING (NOT public.is_account_banned(auth.uid()) AND (user_id=auth.uid() OR public.has_permission(auth.uid(),'mail')));
CREATE POLICY news_response_insert ON public.news_responses FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_account_banned(auth.uid()) AND EXISTS(SELECT 1 FROM public.mail m WHERE m.id=mail_id AND m.kind='system'));
CREATE POLICY news_response_update ON public.news_responses FOR UPDATE TO authenticated USING(NOT public.is_account_banned(auth.uid()) AND (user_id=auth.uid() OR public.has_permission(auth.uid(),'mail'))) WITH CHECK(NOT public.is_account_banned(auth.uid()) AND (user_id=auth.uid() OR public.has_permission(auth.uid(),'mail')));
CREATE TABLE public.news_popup_dismissals(mail_id uuid NOT NULL REFERENCES public.mail(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(mail_id,user_id));
GRANT SELECT,INSERT ON public.news_popup_dismissals TO authenticated; GRANT ALL ON public.news_popup_dismissals TO service_role;
ALTER TABLE public.news_popup_dismissals ENABLE ROW LEVEL SECURITY;
CREATE POLICY news_popup_read ON public.news_popup_dismissals FOR SELECT TO authenticated USING(user_id=auth.uid() AND NOT public.is_account_banned(auth.uid()));
CREATE POLICY news_popup_dismiss ON public.news_popup_dismissals FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_account_banned(auth.uid()) AND EXISTS(SELECT 1 FROM public.mail m WHERE m.id=mail_id AND m.kind='system' AND m.popup));
CREATE OR REPLACE FUNCTION public.validate_news_response() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE m public.mail; BEGIN SELECT * INTO m FROM public.mail WHERE id=NEW.mail_id; IF m.kind<>'system' OR (NEW.choice IS NOT NULL AND (NEW.choice<0 OR NEW.choice>=cardinality(m.poll_options))) THEN RAISE EXCEPTION 'Invalid poll choice'; END IF; IF length(NEW.answer)>2000 OR length(NEW.reply)>2000 THEN RAISE EXCEPTION 'Answer is too long'; END IF; IF NEW.answer<>'' AND NOT m.question_enabled THEN RAISE EXCEPTION 'Questions are disabled'; END IF; IF auth.uid() IS NOT NULL THEN IF TG_OP='INSERT' AND NEW.reply<>'' THEN RAISE EXCEPTION 'Only staff can reply'; END IF; IF TG_OP='UPDATE' THEN IF NEW.mail_id<>OLD.mail_id OR NEW.user_id<>OLD.user_id THEN RAISE EXCEPTION 'Response identity cannot change'; END IF; IF NEW.choice IS DISTINCT FROM OLD.choice AND OLD.choice IS NOT NULL THEN RAISE EXCEPTION 'You have already voted'; END IF; IF NEW.reply IS DISTINCT FROM OLD.reply AND NOT public.has_permission(auth.uid(),'mail') THEN RAISE EXCEPTION 'Only staff can reply'; END IF; IF (NEW.answer IS DISTINCT FROM OLD.answer OR NEW.choice IS DISTINCT FROM OLD.choice) AND NEW.user_id<>auth.uid() THEN RAISE EXCEPTION 'Only the player can edit their response'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_news_response BEFORE INSERT OR UPDATE ON public.news_responses FOR EACH ROW EXECUTE FUNCTION public.validate_news_response();
CREATE TRIGGER audit_news_response AFTER UPDATE ON public.news_responses FOR EACH ROW EXECUTE FUNCTION public.capture_admin_audit();
CREATE POLICY staff_update_news ON public.mail FOR UPDATE TO authenticated USING(user_id IS NULL AND kind='system' AND public.has_permission(auth.uid(),'mail')) WITH CHECK(user_id IS NULL AND kind='system' AND public.has_permission(auth.uid(),'mail'));
CREATE OR REPLACE FUNCTION public.news_poll_totals(_mail uuid) RETURNS TABLE(choice integer,votes bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.choice,count(*) FROM public.news_responses r WHERE r.mail_id=_mail AND r.choice IS NOT NULL AND auth.uid() IS NOT NULL AND NOT public.is_account_banned(auth.uid()) AND EXISTS(SELECT 1 FROM public.mail m WHERE m.id=_mail AND m.kind='system' AND (m.user_id IS NULL OR m.user_id=auth.uid())) GROUP BY r.choice $$;
CREATE OR REPLACE FUNCTION public.news_role_colors() RETURNS TABLE(name text,colors text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.name,s.colors FROM public.staff_roles s WHERE auth.uid() IS NOT NULL AND NOT public.is_account_banned(auth.uid()) ORDER BY s.sort $$;
REVOKE ALL ON FUNCTION public.news_poll_totals(uuid),public.news_role_colors() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.news_poll_totals(uuid),public.news_role_colors() TO authenticated,service_role;